  function install(options){ctx=options;document.addEventListener('change',function(e){if(e.target.id==='bs-player-venue'){venueId=Number(e.target.value);cart={};refresh();}});$('#account-recovery').onclick=function(){identityAction('recovery');};$('#identity-verify-current').onclick=function(){identityAction('verify');};$('#identity-change-contact').onclick=function(){identityAction('contact');};$('#identity-enroll-password').onclick=function(){identityAction('password');};var host=$('#business-player');if(!host)return;$('#rg-method').addEventListener('change',signupMethod);signupMethod();var ref=new URLSearchParams(location.search).get('ref');if(ref)$('#rg-referral').value=ref.slice(0,120);$('#otp-resend').onclick=async function(){this.disabled=true;try{beginVerification(await ctx.api('/api/auth/otp/resend',{method:'POST',body:{challenge_id:activeChallenge.challenge_id}}));}catch(e){ctx.toast(e.message,'error');this.disabled=false;}};$('#form-otp').onsubmit=async function(e){e.preventDefault();var b=this.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;try{var data=await ctx.api('/api/auth/otp/verify',{method:'POST',body:{challenge_id:activeChallenge.challenge_id,otp:$('#otp-code').value.trim()}});if(data.nextChallenge){beginVerification(data.nextChallenge);return;}clearInterval(otpTimer);$('#form-otp').classList.add('hidden');ctx.onAuth(data);ctx.toast('Identity verified. Welcome!','success');}catch(error){ctx.toast(error.message,'error');}finally{b.disabled=false;}};$('#mobile-login-request').onclick=function(){ctx.modal({title:'Mobile OTP login',body:'<div class="field"><label for="bs-login-mobile">Verified Philippine mobile</label><input class="input" id="bs-login-mobile" autocomplete="tel" inputmode="tel" placeholder="+63 917 000 0000"></div>',confirmText:'Send login code',onConfirm:async function(modalHost){beginVerification(await ctx.api('/api/auth/mobile/login',{method:'POST',body:{mobile:$('#bs-login-mobile',modalHost).value.trim()}}));return true;}});};document.querySelectorAll('[data-authtab]').forEach(function(b){b.addEventListener('click',function(){$('#form-otp').classList.add('hidden');clearInterval(otpTimer);});});document.addEventListener('click',function(e){var nav=e.target.closest('[data-panel="panel-business"]');if(nav)refresh();var tab=e.target.closest('[data-bs-view]');if(tab && host.contains(tab)){view=tab.dataset.bsView;render();drawReferral();}var b=e.target.closest('[data-bs-action]');if(b && (host.contains(b) || b.closest('#bs-queue-view') || b.closest('[data-bs-offers]') || b.closest('[data-bs-private-gallery]'))){b.disabled=true;Promise.resolve(action(b.dataset.bsAction,b.dataset.bsId)).catch(function(err){ctx.toast(err.message,'error');}).finally(function(){if(b.isConnected)b.disabled=false;drawReferral();});}});window.addEventListener('pikol-business-change',function(){if(!$('#panel-business-box').classList.contains('hidden'))refresh();});window.addEventListener('online',function(){if(!$('#panel-business-box').classList.contains('hidden'))refresh();});}
  async function loadRewards(){if(!ctx.getUser())return;account=await ctx.api('/api/business/me');}
  function rewardHtml(service,id){var vouchers=(account.loyalty&&account.loyalty.vouchers||[]).filter(function(v){var snapshot=parse(v.snapshot_json,{});return v.state==='available'&&snapshot.reward&&snapshot.reward.service===service&&(!v.expires_at||Date.parse(v.expires_at)>Date.now());});if(!vouchers.length)return '';return '<label class="field"><span class="label">Optional loyalty voucher</span><select class="select" id="'+esc(id)+'"><option value="">Use membership pricing</option>'+vouchers.map(function(v){var r=parse(v.snapshot_json,{}).reward;return '<option value="'+esc(v.code)+'">'+esc(r.name)+' · up to '+money(r.discount_cents)+' reduction</option>';}).join('')+'</select><span class="bs-note">One best eligible price reduction applies. A voucher is consumed only when the service payment is verified.</span></label>';}
  async function reviewLegacy(host,data){var quote=await ctx.api('/api/business/quote',{method:'POST',body:data});if(!Number.isSafeInteger(quote.amountCents)||quote.amountCents<0)throw new Error('The club did not return a valid price');var hash=JSON.stringify(data),prior=host.dataset.bsQuotedInput,amount=host.dataset.bsQuotedAmount;if(prior===hash&&Number(amount)===quote.amountCents)return quote;host.dataset.bsQuotedInput=hash;host.dataset.bsQuotedAmount=String(quote.amountCents);var note=host.querySelector('[data-bs-legacy-quote]');if(!note){note=document.createElement('div');note.className='bs-card';note.setAttribute('data-bs-legacy-quote','');(host.querySelector('.modal-body')||host).appendChild(note);}note.innerHTML='<strong>Club-confirmed service price: '+money(quote.amountCents)+'</strong>'+((quote.benefit||{}).occasion?'<p>Special occasion: '+esc(quote.benefit.occasion.definition&&quote.benefit.occasion.definition.title)+' · Actual reduction '+money(quote.benefit.occasion.discountCents)+'</p>':'')+'<p>Review this current price, then confirm registration. Any selected PIKOL Credit is applied to this total at checkout.</p>';note.scrollIntoView&&note.scrollIntoView({block:'nearest'});return null;}
  async function openVenueLink(){if(venueLinkHandled||!ctx.getUser()||ctx.getUser().terms_required)return;var params=new URLSearchParams(location.search);if(!params.get('venue')&&!params.get('venue_id'))return;var scanned=parseVenueQr(location.href);venueLinkHandled=true;venueId=scanned;view='queue';if(ctx.openBusiness)ctx.openBusiness();await refresh();var candidates=list(catalogue,'open_play_events','openPlayEvents').filter(function(e){if(Number(e.venue_id)!==scanned)return false;var start=Date.parse(e.event_date+'T'+(e.start_time.length===5?e.start_time+':00':e.start_time)+'+08:00'),end=Date.parse(e.event_date+'T'+(e.end_time.length===5?e.end_time+':00':e.end_time)+'+08:00');return start<=Date.now()&&Date.now()<end;});if(candidates.length===1){try{await queue(candidates[0].id);var input=$('#bs-queue-token');if(input)input.value=location.href;}catch(error){ctx.toast(error.message,'info');}}}
  window.PikolBusinessPlayer={install:install,signup:signup,refresh:refresh,updateIdentityUI:updateIdentityUI,loadRewards:loadRewards,rewardHtml:rewardHtml,reviewLegacy:reviewLegacy,offerHtml:offerHtml,openVenueLink:openVenueLink};
